#!/usr/bin/env bash
# Bounded event sourcing (the paper's second provenance mitigation) for the added writers: one run per domain and seed with both
# writers (Inkling, DeepSeek V4.1 Flash), event-writer calls plus a paired executor replay of the saved incremental typed baseline, both executors.
set -u
export PATH="$HOME/.local/bin:/c/Users/mikad/.local/bin:$PATH"
cd "$(dirname "$0")"
LOG="${1:-results/driver_$(basename "$0" .sh).log}"
run() {
  local tag; tag=$(printf '%s
' "$@" | awk '/^--tag$/{getline; print; exit}')
  if [ -n "$tag" ] && ls -d results/*/*__"$tag" >/dev/null 2>&1 && grep -lq '"status": "completed"' results/*/*__"$tag"/manifest.json 2>/dev/null; then echo "=== $(date +%H:%M) SKIP (completed run exists) $tag" >> "$LOG"; return 0; fi
  echo "=== $(date +%H:%M) $*" >> "$LOG"; uv run python -m "$@" >> "$LOG" 2>&1 || echo "FAILED: $*" >> "$LOG"
}
echo "=== $(date +%H:%M) PHASE 29f START" >> "$LOG"

run experiments.run --domain cybersecurity --study event_sourcing --writer-targets inkling_baseten,deepseek_v4_1_flash_baseten --executor-targets gptoss_baseten,deepseek_baseten --source-run "results/cybersecurity/20260907-020100-204117__authorization-memory-writer__paper-writer-s20260812-cybersecurity-inkling" --source-run "results/cybersecurity/20260912-192002-963969__authorization-memory-writer__paper-writer-s20260812-cybersecurity-deepseek_v4_1_flash" --batch-size 6 --estimated-cost-usd 15 --tag "event-s20260812-cybersecurity"
