run experiments.run --domain cybersecurity --study event_sourcing --writer-targets inkling_baseten,deepseek_v4_1_flash_baseten --executor-targets gptoss_baseten,deepseek_baseten --source-run "results/cybersecurity/20260907-040631-133475__authorization-memory-writer__paper-writer-s20260822-cybersecurity-inkling" --source-run "results/cybersecurity/20260912-220613-370189__authorization-memory-writer__paper-writer-s20260822-cybersecurity-deepseek_v4_1_flash" --batch-size 6 --estimated-cost-usd 15 --tag "event-s20260822-cybersecurity"
