run experiments.run --domain finance --study event_sourcing --writer-targets inkling_baseten,deepseek_v4_1_flash_baseten --executor-targets gptoss_baseten,deepseek_baseten --source-run "results/finance/20260912-194855-372742__authorization-memory-writer__paper-writer-s20260821-finance-inkling" --source-run "results/finance/20260912-192850-400540__authorization-memory-writer__paper-writer-s20260821-finance-deepseek_v4_1_flash" --batch-size 6 --estimated-cost-usd 15 --tag "event-s20260821-finance"
run experiments.run --domain finance --study event_sourcing --writer-targets inkling_baseten,deepseek_v4_1_flash_baseten --executor-targets gptoss_baseten,deepseek_baseten --source-run "results/finance/20260912-211450-775567__authorization-memory-writer__paper-writer-s20260822-finance-inkling" --source-run "results/finance/20260912-201505-785068__authorization-memory-writer__paper-writer-s20260822-finance-deepseek_v4_1_flash" --batch-size 6 --estimated-cost-usd 15 --tag "event-s20260822-finance"
